#include <stdio.h>

int solution(int N) {
    int bulb[101] = {0};
    for (int sec = 1; sec <= N; sec++) {
        for (int i = sec; i <= N; i += sec) {
            bulb[i] = 1;
        }
    }
    int count = 0;
    for (int i = 1; i <= N; i++) {
        if (bulb[i] == 1) count++;
    }
    return count;
}

